import{_ as i,c as a,a0 as o,o as r}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"ADR-0001: API 作为唯一正式边界","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-api-boundary.md","filePath":"adr/0001-api-boundary.md"}'),l={name:"adr/0001-api-boundary.md"};function d(t,e,c,n,s,u){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="adr-0001-api-作为唯一正式边界" tabindex="-1">ADR-0001: API 作为唯一正式边界 <a class="header-anchor" href="#adr-0001-api-作为唯一正式边界" aria-label="Permalink to &quot;ADR-0001: API 作为唯一正式边界&quot;">​</a></h1><h2 id="状态-已接受" tabindex="-1">状态：已接受 <a class="header-anchor" href="#状态-已接受" aria-label="Permalink to &quot;状态：已接受&quot;">​</a></h2><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><p>xiaomusic-core 存在多个层次的组件：WebUI、API层（routers）、业务逻辑层（xiaomusic.xiaomusic）、设备控制层（device_player）、播放协调层（PlaybackCoordinator、RelayRuntime）。</p><p>当前问题是：<strong>WebUI 是否可以直接访问 runtime 内部状态？</strong></p><p>在审计中发现：</p><ul><li><code>SiteMediaSourcePlugin</code> 通过 <code>runtime_provider</code> 间接持有 <code>RelayRuntime</code> 引用</li><li><code>RelayRuntime</code> 持有 <code>xiaomusic</code> 引用，可访问任意模块</li><li><code>device_player</code> 直接持有 <code>xiaomusic</code> 引用</li><li>部分 debug 端点（<code>/api/v1/debug/*</code>）暴露内部状态</li></ul><p>如果不加约束，WebUI 可以绕过 API 直接操作内部状态，导致：</p><ol><li>状态同步机制失效（API 不知道 WebUI 的直接修改）</li><li>API 契约被破坏（同样的状态可以通过 API 读、通过内部调用改）</li><li>难以追踪状态变化来源</li><li>测试难度增加（需要 mock 多个内部模块而非只 mock API）</li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p><strong>所有外部访问（WebUI、CLI、外部系统）必须通过 API 进行，不得直接访问 runtime 内部状态。</strong></p><p>具体规定：</p><ol><li><strong>WebUI 只通过 <code>services/</code> 中的 API 调用访问后端</strong>，不直接 import 任何 <code>xiaomusic.*</code> 模块</li><li><strong>API 层内部可以使用 runtime_provider</strong>，但 runtime_provider 本身不暴露给 WebUI</li><li><strong>所有 API 端点必须使用 <code>ApiError</code> 结构化返回</strong>，不得返回裸错误</li><li><strong>debug 端点（<code>/api/v1/debug/*</code>）标记为 <code>include_in_schema=False</code></strong>，生产环境应添加 admin 认证</li><li><strong><code>services/</code> 层只调用正式 API</strong>，不调用 debug 端点</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><h3 id="正面" tabindex="-1">正面 <a class="header-anchor" href="#正面" aria-label="Permalink to &quot;正面&quot;">​</a></h3><ul><li>状态变化路径唯一可追踪</li><li>API 契约清晰，边界稳定</li><li>WebUI 和后端解耦，可以独立演进</li><li>测试时可以 mock API 而不需要 mock 内部模块</li></ul><h3 id="负面" tabindex="-1">负面 <a class="header-anchor" href="#负面" aria-label="Permalink to &quot;负面&quot;">​</a></h3><ul><li>性能开销（通过 HTTP 而非函数调用）</li><li>某些场景（如内部进程调试）需要额外的调试 API</li><li><code>runtime_provider</code> 的使用范围需要明确界定（API 层内部使用，不外泄）</li></ul><h2 id="合规检查" tabindex="-1">合规检查 <a class="header-anchor" href="#合规检查" aria-label="Permalink to &quot;合规检查&quot;">​</a></h2><p>提交前自检：</p><ul><li>[ ] WebUI 是否只通过 <code>services/</code> 访问后端？</li><li>[ ] 新增 API 是否使用 <code>ApiError</code> 返回错误？</li><li>[ ] 是否有代码绕过 API 直接修改 runtime 状态？</li></ul>',21)]))}const m=i(l,[["render",d]]);export{p as __pageData,m as default};
